import { Component } from '@angular/core';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss']
})
export class AppComponent {
  title = 'EncryptDecrypt';
}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Encryption/Decryption UI</title>
    <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet">
    <style>
        .container {
            border: 2px solid black;
            padding: 20px;
            margin-top: 50px;
            width: 50%;
            background-color: #f8f9fa;
        }
        .key-section {
            margin-bottom: 20px;
        }
        .text-section {
            margin-bottom: 20px;
        }
        .btn {
            width: 100%;
        }
        .label-section {
            border: 1px solid black;
            padding: 10px;
            background-color: #e9ecef;
            text-align: center;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="key-section">
            <label for="key" class="form-label">Key</label>
            <input type="text" id="key" class="form-control" placeholder="Enter key here">
        </div>

        <div class="row text-section">
            <div class="col-md-6">
                <label for="plaintext" class="form-label">Enter Plain Text to Encrypt</label>
                <input type="text" id="plaintext" class="form-control" placeholder="Enter plain text">
            </div>
            <div class="col-md-6">
                <label for="encryptedtext" class="form-label">Enter Encrypted Text to Decrypt</label>
                <input type="text" id="encryptedtext" class="form-control" placeholder="Enter encrypted text">
            </div>
        </div>

        <div class="row text-section">
            <div class="col-md-6">
                <button id="encrypt-btn" class="btn btn-primary">Encrypt</button>
            </div>
            <div class="col-md-6">
                <button id="decrypt-btn" class="btn btn-secondary">Decrypt</button>
            </div>
        </div>

        <div class="row">
            <div class="col-md-6">
                <div class="label-section">
                    <span id="encrypted-label">Encrypted Value Will Appear Here</span>
                </div>
            </div>
            <div class="col-md-6">
                <div class="label-section">
                    <span id="decrypted-label">Decrypted Value Will Appear Here</span>
                </div>
            </div>
        </div>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
</body>
</html>
